1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { z } from "zod";
6	import { db } from "./db";
7	import { requireUser } from "./auth";
8	import {
9	  registrarConfigured,
10	  checkDomains,
11	  registerDomain,
12	  renewDomain,
13	  domainInfo,
14	  listRecords,
15	  addRecord,
16	  deleteRecord,
17	  type RegistrantContact,
18	} from "./registrar";
19	import { domainTerm, domainTermPriceCents } from "./billing-terms";
20	import { debitWallet, InsufficientBalanceError } from "./wallet";
21	import { getSettingBool } from "./settings";
22	
23	const DOMAIN_RE = /^[a-z0-9]([a-z0-9-]{0,61}[a-z0-9])?\.[a-z]{2,24}$/;
24	
25	/* ------------------------------------------------------------------ *
26	 * Idempotency helpers
27	 *
28	 * Layer 1 (cheap, in-process): a short-window duplicate-submit guard keyed on
29	 * user+domain. Catches the double-click / impatient-retry case immediately and
30	 * keeps two concurrent requests from both reaching the registrar. Best-effort
31	 * only — it does not survive a restart or span multiple app instances.
32	 *
33	 * Layer 2 (authoritative, in the DB): `Domain.name` is UNIQUE and the
34	 * charge+create runs in one `$transaction`, so a duplicate can never both take
35	 * money and create a second row. Renewal is guarded by an in-transaction expiry
36	 * re-check (charge and expiry advance together atomically).
37	 * ------------------------------------------------------------------ */
38	
39	const SUBMIT_GUARD_MS = 120_000;
40	const inFlightSubmits = new Map<string, number>();
41	
42	function beginSubmit(key: string): boolean {
43	  const now = Date.now();
44	  const heldUntil = inFlightSubmits.get(key);
45	  if (heldUntil !== undefined && heldUntil > now) return false;
46	  if (inFlightSubmits.size > 2000) {
47	    for (const [k, v] of inFlightSubmits) if (v <= now) inFlightSubmits.delete(k);
48	  }
49	  inFlightSubmits.set(key, now + SUBMIT_GUARD_MS);
50	  return true;
51	}
52	
53	function endSubmit(key: string): void {
54	  inFlightSubmits.delete(key);
55	}
56	
57	class DuplicateDomainError extends Error {
58	  constructor() {
59	    super("DUPLICATE_DOMAIN");
60	    this.name = "DuplicateDomainError";
61	  }
62	}
63	
64	const isUniqueConflict = (e: any) => e?.code === "P2002";
65	
66	type RegistrationVerdict = { state: "registered" | "not-registered" | "unknown"; expires?: Date };
67	
68	/**
69	 * After a registrar call fails or times out we must NOT assume the registration
70	 * did not happen — name.com may well have taken the order. Ask the registrar
71	 * before touching the customer's money:
72	 *  - the domain is in our reseller account  -> registered (keep the charge)
73	 *  - the domain is still purchasable        -> not registered (safe to refund)
74	 *  - anything else / registrar unreachable  -> unknown (never auto-refund)
75	 */
76	async function verifyRegistration(domain: string): Promise<RegistrationVerdict> {
77	  try {
78	    const info = await domainInfo(domain);
79	    return { state: "registered", expires: info.expires };
80	  } catch {
81	    /* not in our account, or the API is unhappy — fall through to availability */
82	  }
83	  try {
84	    const [check] = await checkDomains([domain]);
85	    if (check?.available === true) return { state: "not-registered" };
86	  } catch {
87	    /* registrar unreachable */
88	  }
89	  return { state: "unknown" };
90	}
