373	export async function toggleDomainAutoRenew(domainId: string) {
374	  const user = await requireUser();
375	  const domain = await db.domain.findUnique({ where: { id: domainId } });
376	  if (!domain || (domain.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
377	  await db.domain.update({ where: { id: domainId }, data: { autoRenew: !domain.autoRenew } });
378	  revalidatePath(`/dashboard/domains/${domainId}`);
