458	/** One-click: point apex + www at the platform's public IP. */
459	export async function pointDomainAtServer(domainId: string): Promise<{ error?: string }> {
460	  let ctx;
461	  try {
462	    ctx = await ownedDomain(domainId);
463	  } catch (e: any) {
464	    return { error: e.message };
465	  }
466	  const ip = process.env.PUBLIC_IP;
467	  if (!ip) return { error: "Public IP not configured." };
468	  try {
469	    const recs = await listRecords(ctx.domain.name);
470	    for (const r of recs) {
471	      if (["", "www"].includes(r.host) && r.type === "A") await deleteRecord(ctx.domain.name, r.id);
472	    }
473	    await addRecord(ctx.domain.name, { host: "", type: "A", answer: ip, ttl: 300 });
474	    await addRecord(ctx.domain.name, { host: "www", type: "A", answer: ip, ttl: 300 });
475	  } catch (e: any) {
476	    return { error: String(e?.message ?? e).slice(0, 200) };
477	  }
478	  revalidatePath(`/dashboard/domains/${domainId}`);
479	  return {};
480	}
