192	// ---------- Inbound transfers (transfer-in) ----------
193	//
194	// name.com v4 transfers:
195	//   POST /v4/transfers                      { domainName, authCode, privacyEnabled, purchasePrice }
196	//   GET  /v4/transfers                      -> { transfers: [...] }
197	//   GET  /v4/transfers/{domainName}         -> { domainName, email, status }
198	//   POST /v4/transfers/{domainName}:cancel  -> { domainName, email, status }
199	//
200	// A transfer always includes a 1-year extension of the registration, which is
201	// why it is priced off the TLD's RENEWAL rate rather than its promo/first-year
202	// registration rate.
203	
204	/** Compressed sandbox timeline (real transfers take 5-7 days — see SANDBOX_* notes). */
205	const SANDBOX_APPROVAL_MS = 2 * 60_000;
206	const SANDBOX_REGISTRY_MS = 5 * 60_000;
207	
208	/** Deterministic synthetic per-year cost for a TLD in sandbox (integer cents). */
209	function sandboxTldCostCents(domain: string): number {
210	  const tld = domain.slice(domain.lastIndexOf(".") + 1);
211	  let h = 0;
212	  for (const ch of tld) h = (h * 31 + ch.charCodeAt(0)) % 997;
213	  return 900 + (h % 21) * 50; // $9.00 – $19.00
214	}
215	
216	export type TransferCheck = {
217	  domain: string;
218	  /** True when we believe an inbound transfer can be submitted for this name. */
219	  transferable: boolean;
220	  /** Plain-English reason when `transferable` is false. */
221	  reason: string | null;
222	  premium: boolean;
223	  /** RETAIL price the customer pays — covers the transfer + 1 extra year. */
224	  priceCents: number | null;
225	  /** Registrar cost we pay name.com (what we send as `purchasePrice`). */
226	  costCents: number | null;
227	};
228	
229	/**
230	 * The registrar cost of transferring `domain`, in integer cents.
231	 *
232	 * Transfers are billed at the TLD's renewal rate. name.com only reliably prices
233	 * a name it can see, so we try three sources in order and give up honestly:
234	 *   1. the availability result for the domain itself,
235	 *   2. the per-domain pricing endpoint,
236	 *   3. a throwaway probe name on the same TLD — TLD pricing is per-TLD, so an
237	 *      unregistered sibling quotes the same renewal rate.
238	 */
239	async function transferCostCents(domain: string, availability: any): Promise<number | null> {
240	  const own = dollarsToCents(availability?.renewalPrice ?? availability?.purchasePrice);
241	  if (own !== null && own > 0) return own;
242	
243	  try {
244	    const p = await nc("GET", `/v4/domains/${encodeURIComponent(domain)}:getPricing`);
245	    const quoted = dollarsToCents(p?.transferPrice ?? p?.renewalPrice ?? p?.purchasePrice);
246	    if (quoted !== null && quoted > 0) return quoted;
247	  } catch {
248	    /* endpoint unavailable for this TLD/account — fall through to the probe */
249	  }
250	
251	  const tld = domain.slice(domain.indexOf(".") + 1);
252	  try {
253	    const probe = `nxeon-price-probe-${Math.random().toString(36).slice(2, 10)}.${tld}`;
254	    const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [probe] });
255	    const r = (json.results ?? [])[0];
256	    const c = dollarsToCents(r?.renewalPrice ?? r?.purchasePrice);
257	    if (c !== null && c > 0) return c;
258	  } catch {
259	    /* registrar unhappy — no price, caller surfaces that plainly */
260	  }
261	  return null;
262	}
263	
264	/**
265	 * Can this domain be transferred in, and what would it cost? Never throws for a
266	 * "no" answer — a non-transferable name comes back with `transferable: false`
267	 * and a reason the customer can act on.
268	 */
269	export async function checkTransfer(domain: string): Promise<TransferCheck> {
270	  if (SANDBOX) {
271	    // Synthetic: everything is transferable except names containing "locked",
272	    // which exercise the rejected-quote path in staging.
273	    const cost = sandboxTldCostCents(domain);
274	    if (domain.includes("locked")) {
275	      return {
276	        domain,
277	        transferable: false,
278	        reason: "This domain is locked at its current registrar. Unlock it there and try again.",
279	        premium: false,
280	        priceCents: null,
281	        costCents: null,
282	      };
283	    }
284	    return {
285	      domain,
286	      transferable: true,
287	      reason: null,
288	      premium: false,
289	      priceCents: retailCents(cost, await domainMarkupPct()),
290	      costCents: cost,
291	    };
292	  }
293	
294	  const json = await nc("POST", "/v4/domains:checkAvailability", { domainNames: [domain] });
295	  const r = (json.results ?? [])[0];
296	  if (!r) {
297	    return {
298	      domain,
299	      transferable: false,
300	      reason: "We couldn't look this domain up at the registrar. Check the spelling and try again.",
301	      premium: false,
302	      priceCents: null,
303	      costCents: null,
304	    };
305	  }
306	  // Purchasable means nobody owns it — there is nothing to transfer.
307	  if (r.purchasable === true) {
308	    return {
309	      domain,
310	      transferable: false,
311	      reason: "This domain isn't registered anywhere yet, so there's nothing to transfer — register it instead.",
312	      premium: r.premium === true,
313	      priceCents: null,
314	      costCents: null,
315	    };
316	  }
317	  if (r.premium === true) {
318	    return {
319	      domain,
320	      transferable: false,
321	      reason: "Premium domains can't be transferred in automatically — contact support.",
322	      premium: true,
323	      priceCents: null,
324	      costCents: null,
325	    };
326	  }
327	
328	  const cost = await transferCostCents(domain, r);
329	  if (cost === null) {
330	    return {
331	      domain,
332	      transferable: false,
333	      reason: "We can't get a transfer price for this TLD from the registrar right now — contact support.",
334	      premium: false,
335	      priceCents: null,
336	      costCents: null,
337	    };
338	  }
339	  return {
340	    domain,
341	    transferable: true,
342	    reason: null,
343	    premium: false,
344	    priceCents: retailCents(cost, await domainMarkupPct()),
345	    costCents: cost,
346	  };
347	}
