485	export async function addRecord(
486	  domain: string,
487	  rec: { host: string; type: string; answer: string; ttl?: number; priority?: number }
488	): Promise<void> {
489	  await nc("POST", `/v4/domains/${encodeURIComponent(domain)}/records`, {
490	    host: rec.host,
491	    type: rec.type,
492	    answer: rec.answer,
493	    ttl: rec.ttl ?? 300,
494	    ...(rec.priority !== undefined ? { priority: rec.priority } : {}),
495	  });
496	}
497	
498	export async function deleteRecord(domain: string, id: number): Promise<void> {
499	  await nc("DELETE", `/v4/domains/${encodeURIComponent(domain)}/records/${id}`);
500	}
