36	async function nc(method: string, path: string, body?: unknown): Promise<any> {
37	  if (!registrarConfigured()) throw new Error("Domain registrar (name.com) is not configured");
38	  const res = await fetch(`${baseUrl()}${path}`, {
39	    method,
40	    headers: { Authorization: authHeader(), "Content-Type": "application/json" },
41	    body: body !== undefined ? JSON.stringify(body) : undefined,
42	    signal: AbortSignal.timeout(30_000),
43	  });
44	  const text = await res.text();
45	  let json: any = {};
46	  try {
47	    json = text ? JSON.parse(text) : {};
48	  } catch {
49	    /* non-JSON error body */
50	  }
51	  if (!res.ok) {
52	    const msg = json?.message || json?.details || text || `HTTP ${res.status}`;
53	    throw new Error(`name.com: ${msg}`);
54	  }
55	  return json;
56	}
57	
58	function errMsg(e: unknown): string {
59	  return String(e instanceof Error ? e.message : e).slice(0, 200);
60	}
