303	/* ------------------------------------------------------------------ *
304	 * URL forwarding / redirects (name.com URL-forwarding API).
305	 *   GET/POST/DELETE /v4/domains/{domain}/url/forwarding[/{host}]
306	 * Degrades to a persisted-intent Setting + note when unconfigured.
307	 * ------------------------------------------------------------------ */
308	
309	export type Redirect = { host: string; forwardsTo: string; type: string };
310	
311	const redirectStoreKey = (domainId: string) => `domain-redirect:${domainId}`;
312	
313	async function readRedirectIntent(domainId: string): Promise<Redirect[]> {
314	  const s = await db.setting.findUnique({ where: { key: redirectStoreKey(domainId) } });
315	  if (!s?.value) return [];
316	  try {
317	    const parsed = JSON.parse(s.value);
318	    return Array.isArray(parsed) ? parsed : [];
319	  } catch {
320	    return [];
321	  }
322	}
323	
324	async function writeRedirectIntent(domainId: string, list: Redirect[]): Promise<void> {
325	  await db.setting.upsert({
326	    where: { key: redirectStoreKey(domainId) },
327	    create: { key: redirectStoreKey(domainId), value: JSON.stringify(list) },
328	    update: { value: JSON.stringify(list) },
329	  });
330	}
331	
332	export type RedirectsView = { forwards: Redirect[]; live: boolean; note?: string; error?: string };
333	
334	/** List forwardings — live from name.com when possible, else persisted intent. */
335	export async function listRedirects(domainId: string): Promise<RedirectsView> {
336	  let ctx;
337	  try {
338	    ctx = await ownedDomain(domainId);
339	  } catch (e) {
340	    return { forwards: [], live: false, error: errMsg(e) };
341	  }
342	  if (ctx.domain.status === "ACTIVE" && registrarConfigured()) {
343	    try {
344	      const json = await nc("GET", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`);
345	      const forwards: Redirect[] = (json.urlForwarding ?? json.urlForwardings ?? []).map((f: any) => ({
346	        host: f.host ?? "",
347	        forwardsTo: f.forwardsTo ?? "",
348	        type: f.type ?? "redirect301",
349	      }));
350	      return { forwards, live: true };
351	    } catch (e) {
352	      // Fall back to intent store but tell the truth about why.
353	      const forwards = await readRedirectIntent(domainId);
354	      return { forwards, live: false, note: `Live forwarding unavailable (${errMsg(e)}); showing saved intent.` };
355	    }
356	  }
357	  const forwards = await readRedirectIntent(domainId);
358	  return { forwards, live: false, note: "Registrar not connected — showing saved intent that will apply once live." };
359	}
360	
361	const REDIRECT_TYPES = ["redirect301", "redirect302", "masked"] as const;
362	
363	export async function setRedirect(
364	  domainId: string,
365	  hostRaw: string,
366	  forwardsTo: string,
367	  type: string
368	): Promise<RedirectsView> {
369	  let ctx;
370	  try {
371	    ctx = await ownedDomain(domainId);
372	  } catch (e) {
373	    return { forwards: [], live: false, error: errMsg(e) };
374	  }
375	  const host = normHost(hostRaw);
376	  const t = (REDIRECT_TYPES as readonly string[]).includes(type) ? type : "redirect301";
377	  const url = z.string().url().max(2000).safeParse(forwardsTo.trim());
378	  if (!url.success) return { ...(await listRedirects(domainId)), error: "Enter a valid destination URL (including https://)." };
379	
380	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
381	  if (canLive) {
382	    try {
383	      // Upsert: delete any existing forwarding for this host, then create.
384	      try {
385	        await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
386	      } catch {
387	        /* none existed */
388	      }
389	      await nc("POST", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding`, {
390	        host,
391	        forwardsTo: url.data,
392	        type: t,
393	      });
394	    } catch (e) {
395	      return { ...(await listRedirects(domainId)), error: `Registrar rejected the redirect: ${errMsg(e)}` };
396	    }
397	  } else {
398	    const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
399	    list.push({ host, forwardsTo: url.data, type: t });
400	    await writeRedirectIntent(domainId, list);
401	  }
402	
403	  await db.auditLog.create({
404	    data: { userId: ctx.user.id, action: "domain.redirect_set", detail: `${ctx.domain.name} ${host || "@"} -> ${url.data} (${t})${canLive ? " live" : " intent"}` },
405	  });
406	  revalidatePath(`/dashboard/domains/${domainId}`);
407	  const view = await listRedirects(domainId);
408	  return {
409	    ...view,
410	    note: canLive
411	      ? "Redirect saved at name.com via URL forwarding. It can take a little while to take effect."
412	      : "Saved. This redirect will be applied via name.com URL forwarding once the domain is active and the registrar is connected.",
413	  };
414	}
415	
416	export async function deleteRedirect(domainId: string, hostRaw: string): Promise<RedirectsView> {
417	  let ctx;
418	  try {
419	    ctx = await ownedDomain(domainId);
420	  } catch (e) {
421	    return { forwards: [], live: false, error: errMsg(e) };
422	  }
423	  const host = normHost(hostRaw);
424	  const canLive = ctx.domain.status === "ACTIVE" && registrarConfigured();
425	  if (canLive) {
426	    try {
427	      await nc("DELETE", `/v4/domains/${encodeURIComponent(ctx.domain.name)}/url/forwarding/${encodeURIComponent(host)}`);
428	    } catch (e) {
429	      return { ...(await listRedirects(domainId)), error: `Could not remove redirect: ${errMsg(e)}` };
430	    }
431	  }
432	  const list = (await readRedirectIntent(domainId)).filter((r) => normHost(r.host) !== host);
433	  await writeRedirectIntent(domainId, list);
434	  await db.auditLog.create({
435	    data: { userId: ctx.user.id, action: "domain.redirect_delete", detail: `${ctx.domain.name} ${host || "@"}` },
436	  });
437	  revalidatePath(`/dashboard/domains/${domainId}`);
438	  return { ...(await listRedirects(domainId)), note: "Redirect removed." };
439	}
