31	/**
32	 * Mail-platform DNS constants. Customers with a domain registered ELSEWHERE
33	 * publish these at their registrar so mail flows through the Nxeon mail server;
34	 * customers whose domain is inside Nxeon have this managed for them.
35	 */
36	const MAIL_HOST = "mail.nxeon.cloud";
37	const MAIL_MX_PRIORITY = 10;
38	// The mechanism that authorises our sending host; kept separate from the full
39	// record so the deliverability check can look for it inside whatever SPF the
40	// customer already publishes rather than demanding a byte-exact match.
41	const SPF_INCLUDE = "nxeon.cloud";
42	const SPF_VALUE = `v=spf1 include:${SPF_INCLUDE} ~all`;
43	const DMARC_VALUE = "v=DMARC1; p=none; rua=mailto:dmarc@nxeon.cloud";
44	const DKIM_SELECTOR = "dkim";
45	
46	// A syntactically valid registrable domain (labels, no scheme, no trailing dot).
47	const domainRe =
48	  /^(?=.{1,253}$)(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)+[a-z]{2,63}$/;
49	
50	export type DnsRecord = {
51	  type: "TXT" | "MX";
52	  label: string; // human label for the row
53	  host: string; // record host / name
54	  value: string;
55	  priority?: number;
56	  note?: string;
57	};
