338	
339	/**
340	 * Return the DNS records a customer must publish at their registrar for an
341	 * EXTERNAL domain so mail flows through the Nxeon mail server, plus the
342	 * ownership-verification record. Ownership-checked (caller must own the sub).
343	 *
344	 * The DKIM record is fetched from Mailcow (`mcGetDkim`) and cached in
345	 * `dkimRecord`; when Mailcow isn't configured (or has no key yet) a placeholder
346	 * note is returned so the panel still renders.
347	 */
348	export async function getEmailDnsRecords(
349	  subscriptionId: string,
350	): Promise<{
351	  error?: string;
352	  records?: DnsRecord[];
353	  verified?: boolean;
354	  external?: boolean;
355	  cloudflareConnected?: boolean;
356	}> {
357	  const user = await requireUser();
358	
359	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
360	  if (!sub) return { error: "Subscription not found." };
361	  if (sub.userId !== user.id) return { error: "Not your subscription." };
362	
363	  const domain = sub.domainName;
364	
365	  // Resolve the DKIM TXT: prefer the cached value, else fetch + cache from Mailcow.
366	  let dkimTxt = sub.dkimRecord ?? null;
367	  if (!dkimTxt && mailcowConfigured()) {
368	    try {
369	      // Ensure the mail domain exists so Mailcow has generated a DKIM key.
370	      if (!(await mcDomainExists(domain))) {
371	        await mcCreateDomain(domain).catch(() => {});
372	      }
373	      dkimTxt = await mcGetDkim(domain);
374	      if (dkimTxt) {
375	        await db.emailSubscription
376	          .update({ where: { id: sub.id }, data: { dkimRecord: dkimTxt } })
377	          .catch(() => {});
378	      }
379	    } catch (e) {
380	      console.warn(`[mailcow] get dkim ${domain} failed:`, e);
381	    }
382	  }
383	
384	  const records: DnsRecord[] = [
385	    {
386	      type: "TXT",
387	      label: "Ownership verification",
388	      host: `_nxeon-verify.${domain}`,
389	      value: `nxeon-verify=${sub.verifyToken ?? ""}`,
390	      note: "Proves you control this domain. Required before mail is enabled.",
391	    },
392	    {
393	      type: "MX",
394	      label: "Mail routing (MX)",
395	      host: domain,
396	      value: MAIL_HOST,
397	      priority: MAIL_MX_PRIORITY,
398	    },
399	    {
400	      type: "TXT",
401	      label: "SPF",
402	      host: domain,
403	      value: SPF_VALUE,
404	      note: "Authorizes the Nxeon mail server to send for your domain.",
405	    },
406	    {
407	      type: "TXT",
408	      label: "DKIM",
409	      host: `${DKIM_SELECTOR}._domainkey.${domain}`,
410	      value: dkimTxt ?? "",
411	      note: dkimTxt
412	        ? undefined
413	        : "DKIM key is being generated on the mail server — refresh this page shortly to see the value.",
414	    },
415	    {
416	      type: "TXT",
417	      label: "DMARC",
418	      host: `_dmarc.${domain}`,
419	      value: DMARC_VALUE,
420	      note: "Reporting policy for messages that fail SPF/DKIM.",
421	    },
422	  ];
423	
424	  return {
425	    records,
426	    verified: sub.verified,
427	    external: sub.external,
428	    // True for either connection shape (OAuth credentials or a legacy token).
429	    cloudflareConnected: readStoredCloudflare(user.cloudflareTokenEnc) !== null,
430	  };
431	}
432	
433	/**
434	 * Verify that an EXTERNAL domain's owner has published our verification record.
435	 * Resolves the `_nxeon-verify` TXT via DNS and confirms it contains
436	 * `nxeon-verify=<verifyToken>`; the MX pointing at the mail host is accepted as
437	 * corroboration. The result is derived entirely server-side from live DNS —
438	 * client input never decides the outcome. Rate-limited per user + subscription.
439	 */
440	export async function verifyEmailDomain(subscriptionId: string): Promise<Result> {
441	  const user = await requireUser();
442	
443	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
444	  if (!sub) return { error: "Subscription not found." };
445	  if (sub.userId !== user.id) return { error: "Not your subscription." };
446	  if (!sub.external) return { error: "This domain is managed by Nxeon — no verification needed." };
447	  if (sub.verified) return { ok: true };
448	  if (!sub.verifyToken) return { error: "No verification token on this subscription." };
449	
450	  const rl = checkRateLimit(`email-verify:${user.id}:${sub.id}`, {
451	    max: 6,
452	    windowMs: 60_000,
453	  });
454	  if (!rl.ok) {
455	    return { error: `Too many verification attempts. Try again in ${rl.retryAfterSec}s.` };
456	  }
457	
458	  const domain = sub.domainName;
459	  const expected = `nxeon-verify=${sub.verifyToken}`;
460	
461	  // Primary signal: the verification TXT record must contain our exact token.
462	  let tokenFound = false;
463	  try {
464	    const txt = await resolveTxt(`_nxeon-verify.${domain}`);
465	    // Each record may be split into multiple strings — join per-record chunks.
466	    tokenFound = txt.some((chunks) => chunks.join("").trim() === expected);
467	  } catch {
468	    tokenFound = false;
469	  }
470	
471	  // Corroboration: MX pointing at the mail host (does not substitute for the token).
472	  let mxOk = false;
473	  try {
474	    const mx = await resolveMx(domain);
475	    mxOk = mx.some((r) => r.exchange.replace(/\.$/, "").toLowerCase() === MAIL_HOST);
476	  } catch {
477	    mxOk = false;
478	  }
479	
480	  if (!tokenFound) {
481	    return {
482	      error: mxOk
483	        ? "MX is set, but the _nxeon-verify TXT record isn't visible yet. DNS can take a few minutes to propagate."
484	        : "Verification record not found yet. Add the _nxeon-verify TXT record and try again (DNS can take a few minutes).",
485	    };
486	  }
487	
488	  await db.emailSubscription.update({
489	    where: { id: sub.id },
490	    data: { verified: true, verifiedAt: new Date() },
491	  });
492	
493	  await db.auditLog.create({
494	    data: {
495	      userId: user.id,
496	      action: "emailhosting.verify",
497	      detail: `${domain}${mxOk ? " (MX + TXT)" : " (TXT)"}`,
498	    },
499	  });
500	  revalidatePath("/dashboard/email");
501	  return { ok: true };
502	}
503	
504	// ---------- Deliverability self-check ----------
505	
506	/**
507	 * Run the SPF / DKIM / DMARC / MX self-check for a subscription the caller owns.
508	 *
509	 * WHY: "my mail goes to spam" was previously undiagnosable from inside the
510	 * product — the platform owner hit exactly this and had to reach for an external
511	 * tool. This returns pass/fail per record with the value actually observed beside
512	 * the expected one, so the customer can see which DNS row is wrong.
513	 *
514	 * Two correctness rules this depends on:
515	 *   - DNS is read from the ZONE'S AUTHORITATIVE NAMESERVERS, never the system
516	 *     resolver (see lib/mail/deliverability.ts — this host's `hosts: files …`
517	 *     nsswitch order can answer from /etc/hosts and looks like a real lookup).
518	 *   - DKIM is compared against Mailcow's LIVE key, not `sub.dkimRecord`, which is
519	 *     a write-once cache that can outlive a key rotation.
520	 *
521	 * Rate-limited: each run makes several outbound DNS queries plus one Mailcow call.
522	 */
523	export async function checkEmailDeliverability(
524	  subscriptionId: string,
525	): Promise<{ error?: string; report?: DeliverabilityReport }> {
526	  const user = await requireUser();
527	
528	  const sub = await db.emailSubscription.findUnique({ where: { id: subscriptionId } });
529	  if (!sub) return { error: "Subscription not found." };
530	  if (sub.userId !== user.id) return { error: "Not your subscription." };
531	  // A cancelled subscription's domain may since have been taken by another
532	  // customer (the duplicate guard in orderEmailHosting only excludes CANCELLED
533	  // rows), so the old owner must not keep a live probe pointed at it.
534	  if (sub.status === "CANCELLED") return { error: "This subscription is cancelled." };
535	
536	  // NOTE on domain verification: this check deliberately does NOT require
537	  // `sub.verified`, unlike every action that changes mail routing. It only READS
538	  // public DNS and Mailcow's public DKIM key, changes nothing, and an unverified
539	  // domain is precisely the case a customer needs it for — gating it would hide
540	  // the diagnosis exactly when the records are wrong. Ownership of the
541	  // subscription is still required so the panel can't be used to scan arbitrary
542	  // domains through our server.
543	  const rl = checkRateLimit(`email-deliverability:${user.id}`, { max: 10, windowMs: 60_000 });
544	  if (!rl.ok) return { error: `Too many checks. Try again in ${rl.retryAfterSec}s.` };
545	
546	  // LIVE key only. A failure here degrades the DKIM row to "unknown" rather than
547	  // silently comparing against a cached value that may no longer sign anything.
548	  let dkim: { selector: string; txt: string } | null = null;
549	  if (mailcowConfigured()) {
550	    try {
551	      const live = await mcGetDkimDetails(sub.domainName);
552	      if (live) dkim = { selector: live.selector, txt: live.txt };
553	    } catch (e) {
554	      console.warn(`[mailcow] live dkim lookup for ${sub.domainName} failed:`, e);
555	    }
556	  }
557	
558	  try {
559	    const report = await checkDeliverability({
560	      domain: sub.domainName,
561	      mailHost: MAIL_HOST,
562	      spfInclude: SPF_INCLUDE,
563	      spfExpected: SPF_VALUE,
