export async function saveAutoReply(
  input: { enabled: boolean; subject?: string; body?: string; start?: string | null; end?: string | null },
  mailboxAddress?: string,
): Promise<Result> {
  const { user, mailboxId, address, subscription } = await resolveMailbox(mailboxAddress);
  const limited = gate(`mail:settings:${user.id}`, 30, 60_000);
  if (limited) return limited;

  const enabled = Boolean(input.enabled);
  const subject = (input.subject ?? "").trim();
  const body = (input.body ?? "").trim();
  if (subject.length > 200) return { ok: false, error: "Subject is too long (max 200 characters)." };
  if (body.length > 5000) return { ok: false, error: "Message is too long (max 5000 characters)." };
  if (enabled && !body) return { ok: false, error: "Add an auto-reply message before turning it on." };

  const start = fromDateInput(input.start);
  const end = fromDateInput(input.end);
  if (start && end && start.getTime() > end.getTime()) {
    return { ok: false, error: "The start date must be on or before the end date." };
  }

  const blocked = assertRulesAllowed(subscription);
  if (blocked) return blocked;

  const next: MailboxRuleState = {
    ...(await ruleState(mailboxId, address)),
    autoReplyEnabled: enabled,
    autoReplySubject: subject || null,
    autoReplyBody: body || null,
    autoReplyStart: start,
    autoReplyEnd: end,
  };

  try {
    await pushMailboxSieve(next);
  } catch (e) {
    return { ok: false, error: `Couldn't apply the auto-reply on the mail server: ${friendly(e)}` };
  }

  await db.mailbox.update({
    where: { id: mailboxId },
    data: {
      autoReplyEnabled: next.autoReplyEnabled,
      autoReplySubject: next.autoReplySubject,
      autoReplyBody: next.autoReplyBody,
      autoReplyStart: next.autoReplyStart,
      autoReplyEnd: next.autoReplyEnd,
    },
  });

  await db.auditLog
    .create({
      data: {
        userId: user.id,
        action: "mailbox.autoreply",
        detail: `${address} → ${enabled ? "on" : "off"}`,
      },
    })
    .catch(() => {});

  return { ok: true };
}

