/** Reset the mailbox password; returns the new password once for the customer. */
export async function resetPassword(
  mailboxAddress?: string,
): Promise<{ error?: string; password?: string }> {
  const { mailboxId } = await resolveMailbox(mailboxAddress);
  return resetMailboxPassword(mailboxId);
}

/** Turn a thrown error into a short, safe message for the UI. */
function friendly(e: unknown): string {
  const msg = e instanceof Error ? e.message : String(e);
  return msg.replace(/\s+/g, " ").slice(0, 200) || "Something went wrong. Please try again.";
}

