/**
 * Badge for a mailbox's REAL status.
 *
 * Every row used to render a literal `<Badge tone="amber">Provisioning</Badge>`
 * while the column moved through ACTIVE / FAILED / SUSPENDED underneath. When
 * Mailcow was down at creation time `provisionMailboxOnMailcow` set FAILED and
 * `addMailbox` still returned ok, so the row read "Provisioning" forever and
 * mail to that address bounced with nothing on screen suggesting a problem.
 */
function statusBadge(status: string): { tone: "green" | "amber" | "red" | "slate"; label: string } {
  switch (status) {
    case "ACTIVE":
      return { tone: "green", label: "Active" };
    case "FAILED":
      return { tone: "red", label: "Setup failed" };
    case "SUSPENDED":
      return { tone: "slate", label: "Suspended" };
    case "PROVISIONING":
      return { tone: "amber", label: "Provisioning" };
    default:
      // Never invent a friendly label for a value we don't know — show it raw so
      // an unmapped state is visible rather than silently rendered as healthy.
      return { tone: "slate", label: status || "Unknown" };
  }
}

