166	/**
167	 * Prepare the domain for an outbound transfer: unlock the registrar lock and
168	 * retrieve the EPP/auth code from name.com, persisting it to `transferEpp`.
169	 * If the registrar isn't configured we can only surface a previously stored
170	 * code (or ask the customer to contact support). Ownership-checked.
171	 */
172	export async function requestTransferOut(domainId: string): Promise<TransferResult> {
173	  const { user, domain } = await ownedDomain(domainId);
174	
175	  if (domain.status !== "ACTIVE") {
176	    return { error: "The domain must be active before it can be transferred out." };
177	  }
178	
179	  let epp: string | null = domain.transferEpp ?? null;
180	  let unlocked = false;
181	  let registrarHit = false;
182	
183	  if (registrarConfigured()) {
184	    // Unlock — some TLDs can't be unlocked via API; don't hard-fail on this.
185	    try {
186	      await nc("POST", `/v4/domains/${encodeURIComponent(domain.name)}:unlock`, {});
187	      unlocked = true;
188	    } catch {
189	      /* lock state may be managed manually for this TLD */
190	    }
191	    // Retrieve the auth code.
192	    try {
193	      const res = await nc("GET", `/v4/domains/${encodeURIComponent(domain.name)}:getAuthCode`);
194	      if (res?.authCode) {
195	        epp = String(res.authCode);
196	        registrarHit = true;
197	      }
198	    } catch (e) {
199	      if (!epp) return { error: `Could not retrieve the auth code: ${errMsg(e)}` };
200	    }
201	  }
202	
203	  if (!epp) {
204	    return {
205	      error:
206	        "The transfer auth code isn't available yet — the registrar isn't connected. Please contact support to release this domain.",
207	    };
208	  }
209	
210	  await db.domain.update({ where: { id: domainId }, data: { transferEpp: epp } });
211	  await db.auditLog.create({
212	    data: {
213	      userId: user.id,
214	      action: "domain.transfer_out",
215	      detail: `${domainId} unlock=${unlocked} registrar=${registrarHit}`,
216	    },
217	  });
218	  revalidatePath(`/dashboard/domains/${domainId}`);
219	
220	  return {
221	    epp,
222	    unlocked,
223	    registrarHit,
224	    note: unlocked
225	      ? "Registrar lock released and auth code retrieved. Give this code to your new registrar to start the transfer."
226	      : "Auth code retrieved. If your new registrar reports the domain is locked, contact support to release the registrar lock.",
227	  };
228	}
