}): Promise<PointDnsResult> {
  const hostname = cleanHostname(opts.hostname);
  if (!hostname) {
    return { ok: false, error: "Enter a valid domain or subdomain (e.g. example.com)." };
  }

  const ip = String(opts.ip ?? "").trim();
  if (!isIpv4(ip)) {
    return {
      ok: false,
      error: "This server doesn't have a public IPv4 address yet — try again once it's finished provisioning.",
    };
  }

  const resolved = await resolveCloudflareToken(opts.user);
  const token = resolved.token;
  if (!token) return { ok: false, error: resolved.error ?? "Connect Cloudflare first." };

  if (SANDBOX) {
    // Staging never talks to Cloudflare. Report the record we WOULD have written.
    const labels = hostname.split(".");
    return {
      ok: true,
      hostname,
      ip,
      zone: labels.slice(-2).join("."),
      action: "created",
      simulated: true,
    };
  }

  // Find which zone in the account owns this hostname (most specific first).
  let zoneId: string | null = null;
  let zone = "";
  try {
    for (const candidate of zoneCandidates(hostname)) {
      const found = await cfFindZoneId(token, candidate);
      if (found) {
        zoneId = found;
        zone = candidate;
        break;
      }
    }
  } catch (e) {
    if (e instanceof CloudflareError) {
      return { ok: false, error: `Cloudflare error: ${e.message}` };
    }
    throw e;
  }
  if (!zoneId) {
    return {
      ok: false,
      error: `No Cloudflare zone found for ${hostname}. Add the domain to Cloudflare first, or check the Cloudflare account you connected holds this zone.`,
    };
  }

  try {
    const [result] = await cfUpsertRecords(token, zoneId, [
      // proxied:false — DNS-only, so the name resolves straight to the server and
      // Let's Encrypt HTTP-01 validation can reach certbot on it.
      { type: "A", name: hostname, content: ip, proxied: false },
    ]);
    return {
      ok: true,
      hostname,
      ip,
      zone,
      action: result?.action ?? "created",
      simulated: false,
    };
  } catch (e) {
    if (e instanceof CloudflareError) {
      return {
        ok: false,
        error: `Couldn't write the DNS record: ${e.message}. Check the connected Cloudflare account can edit DNS for ${zone}.`,
      };
    }
    throw e;
  }
}

