255	
256	type FakeHostOpts = {
257	  unitText: string;
258	  /** Absolute paths that exist AND are executable on the target. */
259	  executable?: string[];
260	  /** Absolute paths that exist but are not executable. */
261	  presentNotExecutable?: string[];
262	  /** basename -> what `command -v` answers. */
263	  which?: Record<string, string>;
264	  /** absolute path -> what `<path> --version` prints on the TARGET. */
265	  version?: Record<string, string>;
266	  /** absolute path -> what `<path> --version` printed on the SOURCE. */
267	  sourceVersion?: Record<string, string>;
268	  /** Absolute paths that exist on the SOURCE box. */
269	  onSource?: string[];
270	  /** Make symlink creation fail (read-only /usr, race, …). */
271	  symlinkFails?: boolean;
272	  copyFails?: boolean;
273	};
274	
275	function fakeHost(opts: FakeHostOpts) {
276	  const executable = new Set(opts.executable ?? []);
277	  const present = new Set([...(opts.presentNotExecutable ?? []), ...executable]);
278	  const calls: string[] = [];
279	  const host: UnitExecHost = {
280	    readUnitFile: async () => opts.unitText,
281	    isExecutable: async (p) => executable.has(p),
282	    exists: async (p) => present.has(p),
283	    whichSameName: async (base) => opts.which?.[base] ?? "",
284	    versionOf: async (p) => opts.version?.[p] ?? "",
285	    versionOnSource: async (p) => opts.sourceVersion?.[p] ?? "",
286	    symlink: async ({ target, linkPath }) => {
287	      calls.push(`symlink ${linkPath} -> ${target}`);
288	      if (opts.symlinkFails) return false;
289	      executable.add(linkPath);
290	      present.add(linkPath);
291	      return true;
292	    },
293	  };
294	  const said: string[] = [];
295	  return {
296	    host,
297	    calls,
298	    said,
299	    args: {
300	      host,
301	      unit: "nexis-next",
302	      unitFile: "/etc/systemd/system/nexis-next.service",
303	      existsOnSource: async (p: string) => (opts.onSource ?? []).includes(p),
304	      copyFromSource: async (p: string) => {
305	        calls.push(`copy ${p}`);
306	        if (opts.copyFails) return false;
307	        executable.add(p);
308	        present.add(p);
309	        return true;
310	      },
311	      say: async (line: string) => {
312	        said.push(line);
313	      },
314	    },
315	  };
316	}
